-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

CREATE OR REPLACE FUNCTION public.notify_on_offer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_seller uuid;
  v_title text;
begin
  -- An attempt declined at once (below the minimum) isn't news (20261017160000).
  if new.status <> 'open' then return new; end if;
  select l.seller_id, l.title into v_seller, v_title
  from public.listings l where l.id = new.listing_id;

  perform public.notify(
    v_seller, 'offer_new', 'marketplace',
    'New offer on ' || v_title,
    to_char(new.amount_cents / 100.0, 'FM999,999,990.00'),
    '/offers/' || new.id, new.buyer_id
  );
  return new;
end;
$function$;

grant execute on function public.notify_on_offer() to anon;
grant execute on function public.notify_on_offer() to authenticated;
grant execute on function public.notify_on_offer() to public;
grant execute on function public.notify_on_offer() to service_role;
